    let currentRaidIdx = 1;
    let completedQuests = JSON.parse(localStorage.getItem('hunger_completed_quests') || '{}');
    let stashState = JSON.parse(localStorage.getItem('hunger_stash_state') || '{}');

    function saveState() {
      localStorage.setItem('hunger_completed_quests', JSON.stringify(completedQuests));
      localStorage.setItem('hunger_stash_state', JSON.stringify(stashState));
      updateStats();
    }

    function updateStats() {
      const qDone = Object.values(completedQuests).filter(Boolean).length;
      document.getElementById('stat-quests').textContent = `${qDone} / 10`;
      const itemsDone = Object.values(stashState).filter(Boolean).length;
      document.getElementById('stat-items').textContent = `${itemsDone} / ${STASH_ITEMS.length} Items`;
    }

    function selectRaid(idx) {
      currentRaidIdx = idx;

      for (let i = 0; i <= 8; i++) {
        const tab = document.getElementById(`tab-${i}`);
        if (i === idx) {
          tab.className = "raid-tab px-3.5 py-2 rounded-lg border whitespace-nowrap transition-all bg-amber-500 text-slate-950 font-bold border-amber-400 shadow-md";
        } else {
          tab.className = "raid-tab px-3.5 py-2 rounded-lg border whitespace-nowrap transition-all bg-[var(--card,#151921)] border-[var(--border,#262f3d)] text-[var(--muted-foreground,#8e9cae)] hover:text-white";
        }
      }

      const data = RAID_DATA[idx];
      document.getElementById('map-phase-badge').textContent = data.phase;
      document.getElementById('map-title').textContent = data.title;
      const keyBadge = document.getElementById('map-key-badge');
      keyBadge.textContent = data.keyBadge;
      keyBadge.className = `px-2.5 py-1 text-xs font-semibold rounded-md border ${data.keyColor}`;

      document.getElementById('brief-giver').textContent = data.giver;
      document.getElementById('brief-quest-name').textContent = data.quest;
      document.getElementById('brief-desc').textContent = data.desc;

      const multiAlert = document.getElementById('brief-multi-turnin');
      if (idx === 2 || idx === 3) {
        multiAlert.classList.remove('hidden');
      } else {
        multiAlert.classList.add('hidden');
      }

      const btn = document.getElementById('btn-complete-quest');
      if (completedQuests[idx]) {
        btn.textContent = "Completed ✓";
        btn.className = "px-3 py-1.5 rounded-lg text-xs font-bold bg-emerald-500 hover:bg-emerald-400 text-slate-950 transition-colors shadow";
      } else {
        btn.textContent = "Mark Complete";
        btn.className = "px-3 py-1.5 rounded-lg text-xs font-bold bg-amber-500 hover:bg-amber-400 text-slate-950 transition-colors shadow";
      }

      // Populate 4-box Focus Grid
      const focusGrid = document.getElementById('focus-breakdown');
      focusGrid.innerHTML = `
        <div class="bg-[var(--card,#151921)] border border-amber-500/30 rounded-lg p-2.5 space-y-1">
          <div class="font-bold text-amber-300 flex items-center gap-1.5">
            <span>🎯</span> Primary Objective Focus
          </div>
          <div class="text-[var(--foreground,#cbd5e1)] text-[11px] leading-relaxed">${data.focus.primary}</div>
        </div>
        <div class="bg-[var(--card,#151921)] border border-emerald-500/30 rounded-lg p-2.5 space-y-1">
          <div class="font-bold text-emerald-300 flex items-center gap-1.5">
            <span>📦</span> High-Density Container Focus
          </div>
          <div class="text-[var(--foreground,#cbd5e1)] text-[11px] leading-relaxed">${data.focus.loot}</div>
        </div>
        <div class="bg-[var(--card,#151921)] border border-cyan-500/30 rounded-lg p-2.5 space-y-1">
          <div class="font-bold text-cyan-300 flex items-center gap-1.5">
            <span>🗝️</span> Key / Merchant Action
          </div>
          <div class="text-[var(--foreground,#cbd5e1)] text-[11px] leading-relaxed">${data.focus.keys}</div>
        </div>
        <div class="bg-[var(--card,#151921)] border border-purple-500/30 rounded-lg p-2.5 space-y-1">
          <div class="font-bold text-purple-300 flex items-center gap-1.5">
            <span>⚡</span> Post-Raid Turn-In Chain
          </div>
          <div class="text-[var(--foreground,#cbd5e1)] text-[11px] leading-relaxed">${data.focus.postRaid}</div>
        </div>
      `;

      // Route steps
      const stepsOl = document.getElementById('tactical-steps');
      stepsOl.innerHTML = data.steps.map(s => `<li class="leading-relaxed">${s}</li>`).join('');

      // Container targets
      const containerDiv = document.getElementById('container-targets');
      containerDiv.innerHTML = data.containers.map(c => `
        <div class="bg-[var(--background,#0e1015)] border border-[var(--border,#262f3d)] rounded-xl p-3 flex flex-col gap-1">
          <div class="flex items-center justify-between">
            <span class="font-bold text-white text-xs">${c.name}</span>
            <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-400/20 text-amber-300 border border-amber-400/30">${c.chance}</span>
          </div>
          <div class="flex items-center justify-between text-[11px] text-[var(--muted-foreground,#8e9cae)]">
            <span>Density: <strong>${c.count}</strong></span>
            <span class="text-slate-400 italic">${c.note}</span>
          </div>
        </div>
      `).join('');

      // Mob & Loose loot targets
      const mobDiv = document.getElementById('mob-targets');
      if (mobDiv && data.mobs) {
        mobDiv.innerHTML = data.mobs.map(m => `
          <div class="bg-[var(--background,#0e1015)] border border-[var(--border,#262f3d)] rounded-xl p-3 flex flex-col gap-1">
            <div class="flex items-center justify-between">
              <span class="font-bold text-white text-xs flex items-center gap-1.5">
                <span class="text-amber-400">⚔️</span> ${m.name}
              </span>
              <span class="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30">${m.chance}</span>
            </div>
            <div class="flex items-center justify-between text-[11px] text-[var(--muted-foreground,#8e9cae)]">
              <span>Category: <strong class="text-slate-300">${m.type}</strong></span>
              <span class="text-slate-400 italic">${m.note}</span>
            </div>
          </div>
        `).join('');
      }

      // Instant Multi-Image View Switcher
      const hubOverlay = document.getElementById('hub-overlay');
      if (idx === 0 || idx === 8) {
        for (let i = 1; i <= 7; i++) {
          const m = document.getElementById(`map-img-${i}`);
          if (m) m.classList.add('hidden');
        }
        if (hubOverlay) {
          hubOverlay.classList.remove('hidden');
          document.getElementById('hub-overlay-title').textContent = data.title;
          document.getElementById('hub-overlay-desc').textContent = data.desc;
        }
      } else {
        if (hubOverlay) hubOverlay.classList.add('hidden');
        for (let i = 1; i <= 7; i++) {
          const m = document.getElementById(`map-img-${i}`);
          if (m) {
            if (i === idx) {
              m.classList.remove('hidden');
            } else {
              m.classList.add('hidden');
            }
          }
        }
      }
    }

    function toggleActiveQuestComplete() {
      completedQuests[currentRaidIdx] = !completedQuests[currentRaidIdx];
      saveState();
      selectRaid(currentRaidIdx);
    }

    function renderChecklist() {
      const container = document.getElementById('stash-checklist');
      container.innerHTML = STASH_ITEMS.map(item => {
        const checked = !!stashState[item.id];
        return `
          <label class="flex items-center gap-2.5 p-2 rounded-lg border transition-all cursor-pointer ${
            checked 
              ? 'bg-emerald-950/20 border-emerald-800/40 text-emerald-200' 
              : 'bg-[var(--background,#0e1015)] border-[var(--border,#262f3d)] text-slate-300'
          }">
            <input type="checkbox" onchange="toggleStashItem('${item.id}')" ${checked ? 'checked' : ''} class="rounded text-amber-500 focus:ring-0">
            ${EMBEDDED_ICONS[item.id] ? `<img src="${EMBEDDED_ICONS[item.id]}" alt="${item.label}" class="w-7 h-7 object-contain rounded bg-slate-900/60 p-0.5 border border-slate-700/50 flex-shrink-0">` : ''}
            <div class="leading-tight flex-1 min-w-0">
              <div class="font-bold text-xs ${checked ? 'line-through text-emerald-400' : 'text-white'}">${item.label}</div>
              <div class="text-[10px] text-[var(--muted-foreground,#8e9cae)] truncate">${item.vendor}</div>
            </div>
          </label>
        `;
      }).join('');
    }

    function toggleStashItem(id) {
      stashState[id] = !stashState[id];
      saveState();
      renderChecklist();
    }

    function openZoomModal() {
      const activeImg = document.getElementById(`map-img-${currentRaidIdx}`);
      const modalSrc = activeImg ? activeImg.src : (EMBEDDED_MAPS[currentRaidIdx] || `raid${currentRaidIdx}_map.jpg`);
      if (!modalSrc) return;
      document.getElementById('zoom-modal-img').src = modalSrc;
      document.getElementById('zoom-modal-title').textContent = `${RAID_DATA[currentRaidIdx].phase} — ${RAID_DATA[currentRaidIdx].title}`;
      document.getElementById('zoom-modal').classList.remove('hidden');
    }

    function closeZoomModal() {
      document.getElementById('zoom-modal').classList.add('hidden');
    }

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeZoomModal();
    });

    // Init
    selectRaid(1);
    renderChecklist();
    updateStats();
  

console.log('Testing selectRaid for all indices 0 to 8:');
for (let idx = 0; idx <= 8; idx++) {
    selectRaid(idx);
    console.log(`Index ${idx}: quest='${elements['brief-quest-name'].textContent}', steps=${elements['tactical-steps'].innerHTML.length > 0}, conts=${elements['container-targets'].innerHTML.length > 0}, mobs=${elements['mob-targets'].innerHTML.length > 0}`);
}
